), ins AS (
  INSERT INTO public.spot_gpx_tracks (spot_id, gpx_url, trailhead, start_lat, start_lng, km, credit)
  SELECT spot_id, url, th, lat, lng, km, '오라네' FROM v ORDER BY spot_id, d DESC
  ON CONFLICT (spot_id, gpx_url) DO NOTHING
  RETURNING spot_id
)
SELECT count(*) AS inserted FROM ins;

UPDATE public.spots s
SET gpx_url = t.gpx_url, gpx_credit = '오라네'
FROM (SELECT DISTINCT ON (spot_id) spot_id, gpx_url FROM public.spot_gpx_tracks ORDER BY spot_id, id) t
WHERE s.id = t.spot_id AND COALESCE(s.gpx_url, '') = '';
